  1→//! Shared display helpers for step status formatting.
  2→//!
  3→//! These helpers are used by `status`, `last`, and any other command that
  4→//! needs to render [`StepStatus`] values consistently.
  5→
  6→use crate::state::StepStatus;
  7→use crate::ui::{StatusKind, UserInterface};
  8→
  9→/// Return a StatusKind for a step status.
 10→pub fn status_kind(status: &StepStatus) -> StatusKind {
 11→    StatusKind::from(*status)
 12→}
 13→
 14→/// Return the icon string for a step status (TTY output).
 15→pub fn status_icon(status: &StepStatus) -> &'static str {
 16→    status_kind(status).icon()
 17→}
 18→
 19→/// Return a bracketed symbol for a step status (non-TTY output).
 20→pub fn status_symbol(status: &StepStatus) -> &'static str {
 21→    status_kind(status).bracketed()
 22→}
 23→
 24→/// Print a single step's status line, styled by severity.
 25→pub fn show_step_status(ui: &mut dyn UserInterface, name: &str, status: &StepStatus) {
 26→    let kind = status_kind(status);
 27→    let line = format!("  {} {}", kind.icon(), name);
 28→    match status {
 29→        StepStatus::Success => ui.success(&line),
 30→        StepStatus::Failed => ui.error(&line),
 31→        StepStatus::Skipped => ui.warning(&line),
 32→        StepStatus::NeverRun => ui.message(&line),
 33→    }
 34→}
 35→
