//! GitHub Actions output formatter.
//!
//! Formats lint diagnostics as [workflow commands] that GitHub Actions
//! renders as file annotations in pull requests and the Actions log.
//!
//! [workflow commands]: https://docs.github.com/en/actions/writing-workflows/choosing-what-your-workflow-does/workflow-commands-for-github-actions

use super::LintFormatter;
use crate::lint::{LintDiagnostic, Severity};
use std::io::Write;

/// Formats lint output as GitHub Actions workflow commands.
///
/// Each diagnostic becomes a `::error::`, `::warning::`, or `::notice::`
/// annotation. When file and line information is available, GitHub renders
/// these as inline annotations on pull request diffs.
pub struct GithubActionsFormatter;

impl GithubActionsFormatter {
    /// Create a new GitHub Actions formatter.
    pub fn new() -> Self {
        Self
    }

    fn severity_command(severity: Severity) -> &'static str {
        match severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
            Severity::Hint => "notice",
        }
    }
}

impl Default for GithubActionsFormatter {
    fn default() -> Self {
        Self::new()
    }
}

impl LintFormatter for GithubActionsFormatter {
    fn format<W: Write>(
        &self,
        diagnostics: &[LintDiagnostic],
        writer: &mut W,
    ) -> std::io::Result<()> {
        for diag in diagnostics {
            let command = Self::severity_command(diag.severity);
            let title = &diag.rule_id.0;

            match &diag.span {
                Some(span) => {
                    let file = span.file.display();
                    let line = span.start_line;

                    if span.start_col > 1 {
                        writeln!(
                            writer,
                            "::{command} file={file},line={line},col={col},title={title}::{message}",
                            col = span.start_col,
                            message = diag.message,
                        )?;
                    } else {
                        writeln!(
                            writer,
                            "::{command} file={file},line={line},title={title}::{message}",
                            message = diag.message,
                        )?;
                    }
                }
                None => {
                    writeln!(
                        writer,
                        "::{command} title={title}::{message}",
                        message = diag.message,
                    )?;
                }
            }
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lint::{RuleId, Span};

    #[test]
    fn formats_error_as_error_command() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("test-rule"),
            Severity::Error,
            "Something is wrong",
        )
        .with_span(Span::line("config.yml", 10))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(
            output.trim(),
            "::error file=config.yml,line=10,title=test-rule::Something is wrong"
        );
    }

    #[test]
    fn formats_warning_as_warning_command() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("naming-convention"),
            Severity::Warning,
            "Name uses spaces",
        )
        .with_span(Span::line("config.yml", 3))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.starts_with("::warning "));
    }

    #[test]
    fn formats_hint_as_notice_command() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("style-hint"),
            Severity::Hint,
            "Consider renaming",
        )
        .with_span(Span::line("config.yml", 1))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.starts_with("::notice "));
    }

    #[test]
    fn includes_column_when_not_one() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("test-rule"), Severity::Error, "Bad value")
                    .with_span(Span::new("config.yml", 10, 5, 10, 20)),
            ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("col=5"));
    }

    #[test]
    fn omits_column_when_one() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("test-rule"), Severity::Error, "Bad value")
                .with_span(Span::line("config.yml", 10)),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(!output.contains("col="));
    }

    #[test]
    fn omits_file_params_when_no_span() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("global-rule"),
            Severity::Error,
            "Global issue",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(
            output.trim(),
            "::error title=global-rule::Global issue"
        );
        assert!(!output.contains("file="));
        assert!(!output.contains("line="));
    }

    #[test]
    fn formats_multiple_diagnostics() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("r1"), Severity::Error, "First error")
                .with_span(Span::line("a.yml", 1)),
            LintDiagnostic::new(RuleId::new("r2"), Severity::Warning, "A warning")
                .with_span(Span::line("b.yml", 5)),
            LintDiagnostic::new(RuleId::new("r3"), Severity::Hint, "A hint"),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

